// Written implementation reviews and design tasks: examples are evaluation
// scenarios, not claims that code has been executed in the Practice workspace.
const task = (topic, difficulty, slug, title, prompt, objective, requirements, cases, hints, answer, followUp) => ({
    id: `backend-node-${slug}-v1`, career: "Backend Developer", phase: "Node.js", topic,
    title, difficulty, kind: "written", language: "Technical response",
    estimatedTime: difficulty === "Easy" ? "20–30 minutes" : difficulty === "Medium" ? "35–50 minutes" : "50–75 minutes",
    problemStatement: prompt,
    simplerProblem: objective,
    learningObjectives: [objective, `Explain the ${topic} behavior using the supplied scenarios and justify each observable result.`],
    conceptsToReview: [topic, ...hints], prerequisites: ["JavaScript functions, objects, and exceptions"],
    requirements,
    examples: cases.map(([input, output]) => ({ input, output, explanation: `This scenario evaluates: ${objective}` })),
    tests: cases.map(([input, expected], index) => ({ name: `Acceptance scenario ${index + 1}`, input, expected })),
    hints, approach: `${hints[0]} Then use the scenario evidence to distinguish the successful path from the boundary case before proposing a correction.`,
    walkthrough: cases.map(([input, output]) => `${input} → ${output}`).join("\n"),
    solutionCode: answer, solutionLines: answer.split("\n").filter(Boolean),
    completionCriteria: requirements,
    starterCode: "Proposed implementation or diagnosis:\n\nScenario trace and evidence:\n\nBoundary cases and limitations:\n",
    commonMistakes: [], followUp
});

